/* ==========================================================================
   BI Ergonomia / S.I.G.E - ElevaLife
   Fontes Montserrat/Montserrat Alternates embutidas para o gerador de PDF
   (jsPDF nao tem acesso a fontes do CSS/navegador - precisa do arquivo TTF
   embutido via addFileToVFS/addFont). Pedido do Leo: o Laudo em PDF estava
   usando a fonte padrao do jsPDF (helvetica) e cores genericas, sem nenhuma
   relacao com a identidade visual dos 15 anos da ElevaLife (vinho/creme +
   Montserrat) que o proprio site ja usa - ver css/style.css.
   Fontes: Google Fonts (SIL Open Font License), via pacotes @fontsource,
   convertidas de woff2 para ttf (fontTools) so pra poder embutir no jsPDF.
   ========================================================================== */
(function (global) {
  "use strict";
  const FONTES_PDF = {
    MontserratRegular: "",
    MontserratBold: "",
    MontserratAlternatesBold: "",
  };

  // Registra as 3 fontes no VFS de UMA instancia jsPDF (o VFS e por-instancia
  // - tem que chamar de novo pra cada `new jsPDF(...)` criado, nunca uma vez
  // so). Nomeia a familia "Montserrat" (normal/bold) e "MontserratAlternates"
  // (so bold - usada nos titulos, igual ao `font-family` dos <h1>/titulos no
  // site) para bater com a Tipografia definida em palette_15anos.md.
  function registrarFontesPDF(doc) {
    doc.addFileToVFS("Montserrat-Regular.ttf", FONTES_PDF.MontserratRegular);
    doc.addFont("Montserrat-Regular.ttf", "Montserrat", "normal");
    doc.addFileToVFS("Montserrat-Bold.ttf", FONTES_PDF.MontserratBold);
    doc.addFont("Montserrat-Bold.ttf", "Montserrat", "bold");
    doc.addFileToVFS("MontserratAlternates-Bold.ttf", FONTES_PDF.MontserratAlternatesBold);
    doc.addFont("MontserratAlternates-Bold.ttf", "MontserratAlternates", "bold");
  }

  global.BI = global.BI || {};
  global.BI.registrarFontesPDF = registrarFontesPDF;
})(window);
